class Solution {
  private static int digitMask(int v) {
    int mask = 0;
    for (; v > 0; v /= 10) {
      int bit = 1 << (v % 10);
      if ((mask & bit) != 0) return -1;
      mask |= bit;
    }
    return mask;
  }

  public int goodSubtreeSum(int[] vals, int[] par) {
    final long MOD = 1_000_000_007L;
    int n = vals.length, M = 1 << 10;
    long[][] dp = new long[n][M];
    for (int i = 0; i < n; i++) {
      java.util.Arrays.fill(dp[i], -1);
      dp[i][0] = 0;
      int m = digitMask(vals[i]);
      if (m >= 0) dp[i][m] = vals[i];
    }
    int[] head = new int[n], next = new int[n];
    java.util.Arrays.fill(head, -1);
    for (int i = 1; i < n; i++) {
      next[i] = head[par[i]];
      head[par[i]] = i;
    }
    int[] order = new int[n];
    int qh = 0, qt = 0;
    order[qt++] = 0;
    while (qh < qt) {
      int u = order[qh++];
      for (int c = head[u]; c >= 0; c = next[c]) order[qt++] = c;
    }
    long total = 0;
    for (int idx = n - 1; idx >= 0; idx--) {
      int u = order[idx];
      long best = 0;
      for (long v : dp[u]) best = Math.max(best, v);
      total = (total + best) % MOD;
      if (u == 0) continue;
      long[] p = dp[par[u]], merged = p.clone();
      for (int m1 = 0; m1 < M; m1++) {
        if (p[m1] < 0) continue;
        int comp = (M - 1) ^ m1;
        for (int m2 = comp; ; m2 = (m2 - 1) & comp) {
          if (dp[u][m2] >= 0 && p[m1] + dp[u][m2] > merged[m1 | m2])
            merged[m1 | m2] = p[m1] + dp[u][m2];
          if (m2 == 0) break;
        }
      }
      dp[par[u]] = merged;
    }
    return (int) total;
  }
}
